// Copies the site's dataset next to the service so it knows which items exist.
import { cpSync, mkdirSync } from "node:fs";
mkdirSync(new URL("./data/", import.meta.url), { recursive: true });
for (const f of ["utah.js", "utahLegislature.js", "utahBallot.js", "utahLocal.js", "utahSaid.js", "shop.js", "shirtArt.js", "signup.js"]) cpSync(new URL(`../src/data/${f}`, import.meta.url), new URL(`./data/${f}`, import.meta.url));
// Every other open state (generated by scripts/build-states.mjs), with the list of open states.
cpSync(new URL("../src/data/states/", import.meta.url), new URL("./data/states/", import.meta.url), { recursive: true });
console.log("data synced");
